patches.new_code:
const { execFile } = require('child_process');

exports.runPing = (target, callback) => {
    if (!/^[A-Za-z0-9.:-]+$/.test(target)) {
        return callback(new Error('Invalid target'));
    }
    return execFile('ping', ['-c', '4', target], { timeout: 5000 }, (error, stdout, stderr) => {
        if (error) {
            return callback(error);
        }
        callback(null, stdout);
    });
};

