BLOCKED_HOSTS = {"169.254.169.254", "localhost", "127.0.0.1", "::1"}

def fetch_url(url):
    parsed = urlparse(url)
    if parsed.scheme not in ALLOWED_SCHEMES:
        raise ValueError("Only HTTPS URLs are allowed")
    if parsed.hostname in BLOCKED_HOSTS or parsed.hostname.endswith(".internal"):
