pub async fn fetch(url: &str) -> Result<(), Box<dyn std::error::Error>> {
    let parsed = reqwest::Url::parse(url)?;
    let allowed_hosts = ["example.com", "api.internal"];
    let host = parsed.host_str().ok_or("missing host")?;
    if parsed.scheme() != "https" || !allowed_hosts.contains(&host) {
        return Err("blocked url".into());
    }
    let _ = reqwest::get(parsed).await?;
    Ok(())
}

